        u_xlatb22 = u_xlat2.x<u_xlat22.x;
        if(u_xlatb22){
            u_xlat22.x = _radius * 0.699999988 + 0.0149999997;
            u_xlat0.xy = u_xlat0.xy * vec2(5.0, 5.0);
            u_xlat34 = u_xlat22.x * u_xlat22.x + (-u_xlat34);
            u_xlat34 = sqrt(u_xlat34);
            u_xlat22.x = u_xlat34 / u_xlat22.x;
            u_xlat0.xy = u_xlat0.xy / u_xlat22.xx;
            u_xlat2.xz = u_xlat0.xy;
            u_xlat22.x = 0.0;
            u_xlat34 = 1.0;
            u_xlat35 = 0.0;
            while(true){
                u_xlatb3 = u_xlat35>=4.0;
                if(u_xlatb3){break;}
                u_xlat3.xy = vec2(u_xlat34) * u_xlat2.xz;
                u_xlat25.xy = floor(u_xlat3.xy);
                u_xlat3.zw = u_xlat25.xy * vec2(123.339996, 233.529999);
                u_xlat3 = fract(u_xlat3);
                u_xlat4.xy = u_xlat3.zw + vec2(23.2339993, 23.2339993);
                u_xlat4.x = dot(u_xlat3.zw, u_xlat4.xy);
                u_xlat25.xy = u_xlat3.zw + u_xlat4.xx;
                u_xlat25.x = u_xlat25.y * u_xlat25.x;
                u_xlat25.x = fract(u_xlat25.x);
                u_xlat25.x = u_xlat25.x * 1000.0;
                u_xlat3.xy = u_xlat3.xy + vec2(-0.5, -0.5);
                u_xlat4.x = sin(u_xlat25.x);
                u_xlat5.x = cos(u_xlat25.x);
                u_xlat6.x = sin((-u_xlat25.x));
                u_xlat6.y = u_xlat5.x;
                u_xlat6.z = u_xlat4.x;
                u_xlat4.x = dot(u_xlat3.xy, u_xlat6.yz);
                u_xlat4.y = dot(u_xlat3.xy, u_xlat6.xy);
                u_xlat3.x = u_xlat4.x * 10.0 + 0.100000001;
                u_xlat3.x = sin(u_xlat3.x);
                u_xlat14 = dot(u_xlat4.xy, u_xlat4.xy);
                u_xlat14 = u_xlat14 + -0.25;
                u_xlat14 = u_xlat14 * -4.0;
                u_xlat14 = max(u_xlat14, 0.0);
                u_xlat25.x = u_xlat14 * -2.0 + 3.0;
                u_xlat14 = u_xlat14 * u_xlat14;
                u_xlat14 = u_xlat14 * u_xlat25.x;
                u_xlat3.x = u_xlat14 * u_xlat3.x;
                u_xlat3.x = u_xlat3.x / u_xlat34;
                u_xlat22.x = u_xlat22.x + u_xlat3.x;
                u_xlat3.x = dot(u_xlat2.xz, vec2(0.540000021, 0.839999974));
                u_xlat3.y = dot(u_xlat2.xz, vec2(-0.839999974, 0.540000021));
                u_xlat2.xz = vec2(u_xlat35) + u_xlat3.xy;
                u_xlat34 = u_xlat34 + u_xlat34;
                u_xlat35 = u_xlat35 + 1.0;
            }
            u_xlat0.x = u_xlat22.x * 0.266666681 + 0.5;
            u_xlat13 = u_xlat0.x * u_xlat13;
        }
        u_xlat0.x = u_xlat33 + u_xlat13;
        u_xlat1.xyz = u_xlat0.xxx * _color2.xyz + u_xlat1.xyz;
    }
    u_xlat0.xyz = min(u_xlat1.xyz, vec3(1.0, 1.0, 1.0));
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0.w = 1.0;
    u_xlat0 = u_xlat0 + u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
